cat > src/lib/users.ts <<'EOF'
import { headers } from "next/headers";
import { auth } from "@/lib/auth";
import { db } from "@/lib/db";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = { id: string; email: string; name: string; createdAt: string };

// Users live in Better Auth's `user` table; this maps rows to the app's User type.
function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    createdAt: String(row.createdAt).slice(0, 10),
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare('SELECT id, email, name, createdAt FROM "user" ORDER BY createdAt')
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare('SELECT id, email, name, createdAt FROM "user" WHERE id = ?')
    .get(id) as UserRow | undefined;
  return row && toUser(row);
}

// Resolves the signed-in user from the session cookie, or undefined if signed out.
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? getUser(session.user.id) : undefined;
}
EOF
cat > src/components/auth-form.tsx <<'EOF'
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const isSignUp = mode === "sign-up";

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    setPending(true);
    const form = new FormData(e.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));
    const { error } = isSignUp
      ? await authClient.signUp.email({ email, password, name: String(form.get("name")) })
      : await authClient.signIn.email({ email, password });
    setPending(false);
    if (error) return setError(error.message ?? "Something went wrong");
    router.push("/dashboard");
    router.refresh();
  }

  const input = "w-full rounded border border-black/20 bg-transparent px-3 py-2 text-sm";
  const button = "w-full rounded bg-foreground px-3 py-2 text-sm text-background disabled:opacity-50";

  return (
    <main className="mx-auto max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create account" : "Sign in"}</h1>
      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isSignUp && <input name="name" placeholder="Name" required className={input} />}
        <input name="email" type="email" placeholder="Email" required className={input} />
        <input
          name="password"
          type="password"
          placeholder="Password (min 8 characters)"
          minLength={8}
          required
          className={input}
        />
        {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
        <button type="submit" disabled={pending} className={button}>
          {isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>
      <button
        type="button"
        className={`${button} mt-3 !bg-transparent !text-foreground border border-black/20`}
        onClick={() => authClient.signIn.social({ provider: "google", callbackURL: "/dashboard" })}
      >
        Continue with Google
      </button>
      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? (
          <>Have an account? <Link href="/sign-in" className="underline">Sign in</Link></>
        ) : (
          <>New here? <Link href="/sign-up" className="underline">Create an account</Link></>
        )}
      </p>
    </main>
  );
}
EOF
